#!/usr/bin/env python3
"""Apply Package 6 deterministic preventive policy with atomic backups."""

from __future__ import annotations

import argparse
import base64
from datetime import datetime
import hashlib
from pathlib import Path
import py_compile
import shutil
import tempfile
import zlib


FILES = {
    'src/thesis_core/thesis_core/safety_supervisor_node.py': {'expected': 'fbb4aeaa32696b6f16f55d099b95c38aed2b97d4847ae91f8e77506fbc3a1534', 'desired': '9ecbe45bf67ad1b06e9f94546612a48aab937d661b443b62182cbbc0cbdea4d0', 'payload': ''},
    'src/thesis_simulation/thesis_simulation/simulation_command_adapter.py': {'expected': 'b41ff7b669abbf146b6dad42cabc992ba9de878fc80d1e52ab36c4d415e194fe', 'desired': 'ce6fac834551cc1c65b5bae9cf64f1cb9502a7b89a670144fbb78586355048d5', 'payload': ''},
    'src/thesis_core/thesis_core/safety_policy.py': {'expected': None, 'desired': '0aec287efbe93d1d3cfbaddbd074a35522352f282217e347803b56cb22b6ce69', 'payload': ''},
    'src/thesis_core/test/test_safety_policy.py': {'expected': None, 'desired': 'b3967a4c4398eab0281f5c5341fa54e7280453c4aafeb26b009b3809e9f823ec', 'payload': ''},
}


def digest(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument(
        '--workspace',
        type=Path,
        default=Path.home() / 'Escritorio' / 'TESIS_2_IMPLEMENTATION',
    )
    return parser.parse_args()


def main() -> int:
    workspace = parse_args().workspace.resolve()
    if not workspace.is_dir():
        raise SystemExit(f'ERROR: workspace inexistente: {workspace}')

    desired = {
        relative: zlib.decompress(base64.b64decode(metadata['payload']))
        for relative, metadata in FILES.items()
    }
    pending = []
    for relative, metadata in FILES.items():
        target = workspace / relative
        if target.exists():
            current_hash = digest(target.read_bytes())
            if current_hash == metadata['desired']:
                print(f'YA_ACTUALIZADO={relative}')
                continue
            if metadata['expected'] is None:
                raise SystemExit(
                    f'ERROR: archivo nuevo ya existe con otro contenido: {target}'
                )
            if current_hash != metadata['expected']:
                raise SystemExit(
                    f'ERROR: hash inesperado en {target}\n'
                    f'actual={current_hash}\n'
                    f'esperado={metadata["expected"]}\n'
                    'No se modificó ningún archivo.'
                )
        elif metadata['expected'] is not None:
            raise SystemExit(f'ERROR: falta archivo requerido: {target}')
        pending.append(relative)

    for relative, data in desired.items():
        if relative.endswith('.py'):
            compile(data, str(workspace / relative), 'exec')

    if not pending:
        print('RESULTADO_APLICACION=YA_APLICADO')
        return 0

    backup = (
        Path.home()
        / 'RESPALDO_TESIS_PAQUETE6'
        / datetime.now().strftime('%Y%m%d_%H%M%S')
    )
    backup.mkdir(parents=True, exist_ok=False)

    for relative in pending:
        target = workspace / relative
        if target.exists():
            destination = backup / relative
            destination.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(target, destination)

    for relative in pending:
        target = workspace / relative
        target.parent.mkdir(parents=True, exist_ok=True)
        with tempfile.NamedTemporaryFile(
            mode='wb',
            dir=target.parent,
            prefix=f'.{target.name}.paquete6.',
            delete=False,
        ) as stream:
            stream.write(desired[relative])
            temporary = Path(stream.name)
        temporary.replace(target)

    for relative in FILES:
        if relative.endswith('.py'):
            py_compile.compile(
                str(workspace / relative),
                doraise=True,
            )

    print(f'RESPALDO={backup}')
    for relative in FILES:
        target = workspace / relative
        print(f'SHA256={digest(target.read_bytes())}  {relative}')
    print('RESULTADO_APLICACION=PASS')
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
